import sqlite3
from statistics import mean

def calculate_offsets():
    con = sqlite3.connect("file:data/inspection.sqlite?mode=ro", uri=True)
    con.row_factory = sqlite3.Row

    # Get certified values
    certified = {}
    for row in con.execute("SELECT artefact_id, certified_um FROM reference_parts"):
        certified[row["artefact_id"]] = row["certified_um"]

    # Get measurements after 2026-05-04 (for window_post)
    offsets = {"CMM-1": [], "CMM-2": []}
    for row in con.execute("SELECT * FROM reference_measurements WHERE measured_on >= '2026-05-04'"):
        m_id = row["machine_id"]
        a_id = row["artefact_id"]
        measured = row["measured_um"]
        if a_id in certified:
            offsets[m_id].append(measured - certified[a_id])

    for m_id, vals in offsets.items():
        if vals:
            print(f"{m_id} average offset: {mean(vals):.2f} um (n={len(vals)})")
        else:
            print(f"{m_id} no measurements found")

    con.close()

if __name__ == "__main__":
    calculate_offsets()

